DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `EmployeeSalesbyCountry`(in AtBeginning_Date Datetime,in AtEnding_Date Datetime)
BEGIN
  SELECT Employees.Country,
         Employees.LastName,
         Employees.FirstName,
            Orders.ShippedDate,
            Orders.OrderID,
 `OrderSubtotals`.Subtotal AS SaleAmount
FROM Employees
 JOIN Orders ON Employees.EmployeeID = Orders.EmployeeID
      JOIN `OrderSubtotals` ON Orders.OrderID = `OrderSubtotals`.OrderID
WHERE Orders.ShippedDate Between AtBeginning_Date And AtEnding_Date;

END ;;
DELIMITER ;
